def trace(input_data):
    sess = TraceSession("Recursive Binary Search", input_data,
        pseudocode=[
            "search(l, r):",
            "  if l > r: return -1",
            "  mid = (l+r)//2",
            "  if nums[mid] == target: return mid",
            "  elif nums[mid] < target: return search(mid+1, r)",
            "  else: return search(l, mid-1)",
            "Start with search(0, n-1)"
        ])
    nums = input_data["nums"]
    target = input_data["target"]
    arr = sess.array("nums", nums)
    frames = sess.tree("call_stack")
    answer = None
    def recursive_search(l, r):
        with frames.frame(f"search({l},{r})"):
            arr.highlight_range(l, r, role="interval")
            if l > r:
                sess.note("Empty interval -> return -1")
                return -1
            mid = (l + r) // 2
            arr.highlight(mid, role="current")
            with sess.step(f"Compare nums[{mid}]={nums[mid]} with {target}"):
                if nums[mid] == target:
                    sess.note(f"Found target at index {mid}")
                    return mid
                elif nums[mid] < target:
                    sess.note(f"{nums[mid]} < {target}, search right half")
                    return recursive_search(mid + 1, r)
                else:
                    sess.note(f"{nums[mid]} > {target}, search left half")
                    return recursive_search(l, mid - 1)
    answer = recursive_search(0, len(nums) - 1)
    sess.result(answer)
    trace = sess.to_trace()
    for event in trace["events"]:
        op = event.get("op")
        targets = [t.get("id", "") for t in event.get("targets", [])]
        reas = event.get("reason", "")
        if op == "create" and "nums" in targets:
            event["code_line"] = 2
        elif op == "create" and "call_stack" in targets:
            event["code_line"] = 11
        elif op == "enter":
            event["code_line"] = 4
        elif op == "exit":
            event["code_line"] = 5
        elif op == "highlight" and "interval" in str(event.get("role")):
            event["code_line"] = 4
        elif op == "highlight" and "current" in str(event.get("role")):
            event["code_line"] = 6
        elif op == "note":
            if "target" in reas:
                event["code_line"] = 7
            elif "right half" in reas:
                event["code_line"] = 9
            elif "left half" in reas:
                event["code_line"] = 11
            else:
                event["code_line"] = 5
        elif event.get("role") == "answer" or "answer" in targets:
            event["code_line"] = 11
        else:
            event["code_line"] = 6
    return trace
